# Generated by build.py from recipe.yml for recipe smtp-answer-try-later. Do not edit.
set -e
cd "$(dirname "$0")"
awk '{printf "%s\r\n", $0}' > order.eml <<'EOF'
From: app@example.com
To: ann@example.com
Subject: Order 1042 has shipped

Your order is on its way.
EOF
surl -v --log-file surl.log --mail-domain example.com --mailbox app@example.com:apppass --mailbox ann@example.com:annpass --fault "error;scheme=smtp;command=RCPT;reply=451 4.3.0 try later;times=1" smtp://127.0.0.1:8080/ imap://127.0.0.1:8081/ &
sleep 1
curl -s --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt ann@example.com -T order.eml -w "%{response_code}\n" "smtp://127.0.0.1:8080/{first,second}"
kill $(jobs -p)
